import{_ as i,o as t,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2026-05-20","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2026-05-20","outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-20.md","filePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-20.md","lastUpdated":null}'),a={name:"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-20.md"};function n(r,e,s,c,p,u){return t(),l("div",null,[...e[0]||(e[0]=[o('<p>I&#39;m putting together the meeting summary blog post now.--- title: Ceph RGW Refactoring Meeting 2026-05-20 date: 2026-07-10 updated: 2026-07-11 tags:</p><ul><li>RGW</li><li>加密</li><li>压缩</li><li>性能优化</li><li>会议纪要 categories:</li><li>视频总结 subtitle: Ceph_RGW_Refactoring_Meeting_2026-05-20</li></ul><hr><h1 id="ceph-rgw-refactoring-会议纪要-2026-05-20" tabindex="-1">Ceph RGW Refactoring 会议纪要（2026-05-20） <a class="header-anchor" href="#ceph-rgw-refactoring-会议纪要-2026-05-20" aria-label="Permalink to &quot;Ceph RGW Refactoring 会议纪要（2026-05-20）&quot;">​</a></h1><p>本次会议聚焦于 RGW（Rados Gateway）在传输层安全、server-side encryption 以及 life cycle 压缩转换等方面的重构与改进，主要讨论了 TLS 版本策略、GCM 加密的 chunk size 选择，以及 dedupe（去重）与 object packing（对象打包）之间的关系。以下为详细纪要。</p><h2 id="一、tls-1-2-默认配置的取舍" tabindex="-1">一、TLS 1.2 默认配置的取舍 <a class="header-anchor" href="#一、tls-1-2-默认配置的取舍" aria-label="Permalink to &quot;一、TLS 1.2 默认配置的取舍&quot;">​</a></h2><p>第一个议题由 Casey 提出。起因是他在为前端配置 OpenSSL 以支持 post-quantum（后量子）算法时做了一些更新，注意到当前默认会启用 TLS 1.2。</p><p><strong>背景与讨论：</strong></p><ul><li>TLS 1.3 已经推出并被广泛采用相当长的时间，Casey 因此考虑是否要从默认配置中移除 TLS 1.2。</li><li>作为对照，他检查了 Nginx（Engine X）的做法，发现其仍然默认开启 TLS 1.2。Matt 也提到 TLS 1.2 目前仍被认为是安全的。</li><li>但另有与会者指出，他读到的相关说明存在自相矛盾之处：即便声称 TLS 1.2 安全的文档，也在随后几句里暗示&quot;用户应考虑改用其他方案&quot;。</li><li>有成员反馈，在其所在环境中该问题已被 flag，且已经在强制使用 TLS 1.3，认为强制使用 1.3 是较好的实践。</li></ul><p><strong>决定事项：</strong></p><ul><li>从 Umbrella 的默认配置中移除 TLS 1.2，并通过 release note 记录该变更。</li><li>对于仍需要 TLS 1.2 的用户，通过文档说明如何重新开启。</li><li>Casey 已提交一个 draft pull request 实现该移除并附带 release note；获得与会者一致同意后，他将把该 PR 设为 ready for review，供大家 review 与 approve。</li></ul><p><strong>后续行动：</strong></p><ul><li>Casey 计划撰写一篇 blog post，说明这些变更以及相关的 post-quantum 改动的思路（后量子相关工作更多来自 Rook 项目，预计 Rook 会自行宣传）。</li></ul><h2 id="二、gcm-server-side-encryption-的-chunk-size-pr-67246" tabindex="-1">二、GCM server-side encryption 的 chunk size（PR 67246） <a class="header-anchor" href="#二、gcm-server-side-encryption-的-chunk-size-pr-67246" aria-label="Permalink to &quot;二、GCM server-side encryption 的 chunk size（PR 67246）&quot;">​</a></h2><p>第二个议题由 Matthew 提出，涉及为 server-side encryption 增加 GCM 支持的 PR 67246。</p><p><strong>当前状态与争议点：</strong></p><ul><li>Matthew 采纳了一位 reviewer 的意见，将 chunk size 默认设为 64K。他担心这一改动对 dedupe 可能造成的影响，原本希望 Ben 或 Gabriel（Gabby）能参与讨论。</li><li>该值是可配置的：所有 GCM 对象上都会写入一个 attribute，通过 Rados Gateway 重启即可在 64K 与 4K 之间切换。Matthew 已测试过最高 1 MB 的情况，但为顺利合并本 PR，计划先只支持 4K 与 64K。</li></ul><p><strong>核心矛盾——性能 vs 小对象开销：</strong></p><ul><li>64K chunk size 对大对象有性能优势，但对大量 4K、16K 等小对象的集群会带来显著的 overhead。</li><li>Casey 建议：上传时可以根据 incoming object 的大小来动态选择合适的 chunk size（小对象用 4K，大对象用更大的值），从而避免让管理员配置一个&quot;一刀切&quot;的 chunk size。这一动态方案无需阻塞本 PR 合并，可后续实现。</li><li>也有人提出可以为 multipart uploads 单独设一个 config option，因为分片上传使用更大的 block size 通常是安全的；但考虑到后续还会有 follow-up 改动，最终倾向于暂不引入新的 config option。</li></ul><p><strong>Gabby 与 Matt 的意见：</strong></p><ul><li>Gabby 指出 object packing 仍属未来工作，如果现在就有需求，应先有一个可用方案。</li><li>讨论认为，未来若聚焦于 packing small objects（小对象打包），可能会降低对可变 chunk size 的需求；同时应权衡收益与因条件分支、metadata 复杂化带来的潜在 bug 与维护负担。</li><li>关键前提得到确认：chunk size 以 attribute 形式写入对象，读取时可据此 attribute 推导出 chunk size，因此该信息可被低成本恢复。</li></ul><p><strong>决定事项：</strong></p><ul><li>考虑到 CBC 以及压缩等其他场景普遍使用 4K chunk size，为保持一致性、避免难以察觉的 regression，本 PR 暂时将 chunk size 保持为 4K（回退掉 64K 及新加的 config option）。</li><li>待日后有更好的判断逻辑（例如根据对象大小动态决定何时提升 chunk size）后，再通过单独的 PR 实现 dynamic chunk size。这被判定为一个性能层面的次要优化，涉及&quot;整体最优&quot;的定性判断，不应阻塞当前 feature。</li></ul><p><strong>后续行动：</strong></p><ul><li>Matthew 修改 PR 的最后一个 commit，移除 config option 并将默认值改回 4K。</li><li>由 Casey 或 Matthew 在 PR 中回复 Marcus，总结本次会议的决定。</li><li>创建一个 tracker issue 记录 dynamic chunk size 等 follow-up 想法。</li><li>目标是让该 feature 赶上 Umbrella 版本；即便进入 code freeze，只要 Adam 与 Eric 支持，仍计划将其纳入。</li></ul><h2 id="三、life-cycle-压缩转换支持-pr-67725" tabindex="-1">三、life cycle 压缩转换支持（PR 67725） <a class="header-anchor" href="#三、life-cycle-压缩转换支持-pr-67725" aria-label="Permalink to &quot;三、life cycle 压缩转换支持（PR 67725）&quot;">​</a></h2><p>Matthew 还提到 PR 67725，用于为 life cycle transitions 增加 compress/decompress（压缩与解压）支持。</p><ul><li>该 PR 此前带有 &quot;needs to discuss&quot; 标签，Adam 已 approve。</li><li>Casey 已更新标签，将其置为 &quot;needs QA&quot;。</li></ul><h2 id="四、dedupe、encryption-与-object-packing-的关系" tabindex="-1">四、dedupe、encryption 与 object packing 的关系 <a class="header-anchor" href="#四、dedupe、encryption-与-object-packing-的关系" aria-label="Permalink to &quot;四、dedupe、encryption 与 object packing 的关系&quot;">​</a></h2><p>在讨论 chunk size 时，延伸出关于 dedupe 与 encryption 的问题。</p><p><strong>Gabby 的说明：</strong></p><ul><li>dedupe 基于 clear text（明文），因为 e-tag 是明文，所以 dedupe 并不关心 encryption 如何实现。</li><li>目前 encryption 尚不支持 dedupe，Gabby 正在推进 compression（同样基于明文）的相关工作。</li><li>之前 Matthew 在议程中提到的&quot;dedupe 是否受 block size 影响&quot;，实际上关注点应是 object packing——packing 会把小对象更频繁地聚合成较大的分组，而非 dedupe 直接受 block size 影响。</li></ul><p><strong>关于加密对象的 dedupe：</strong></p><ul><li>有人对&quot;对使用不同 key 加密的对象做 dedupe&quot;表示困惑。Gabby 解释：在 server-side 场景下，不同 key 是因为实现了 per-bucket key（每个 bucket 各有自己的 key），而非用户提供了不同 key。</li><li>这类似于以往一些 lock box 设计的思路。已有用户在提出此类需求并给出方案。</li><li>该行为将由配置（Yaml）控制，甚至可以默认 disable，只对明确表示&quot;不在意不同 bucket 加密、视其为相同&quot;的客户开启。Gabby 表示仍需进一步理解客户的真实诉求，希望在 London（Seth Days）与客户面谈时了解更多。</li></ul><p><strong>compression vs encryption 的现状小结：</strong></p><ul><li>Compression：相对简单、可行，只是需要做更多操作，Gabby 正在收尾与完善，力争在 London 的 Seth Days 前完成。</li><li>Encryption：仍处于 hold 状态。技术上可行，但存在&quot;是否应该做&quot;的开放问题——尤其涉及需要维护已删除 bucket key 副本的机制，以及可能引入的安全风险。客户可能出于安全考虑明确表示不希望这样做，因此该方向仍待厘清。</li></ul><h2 id="五、会议小结" tabindex="-1">五、会议小结 <a class="header-anchor" href="#五、会议小结" aria-label="Permalink to &quot;五、会议小结&quot;">​</a></h2><p>本次会议在 TLS 1.2 移除、GCM chunk size 回退至 4K 等事项上达成了明确共识，并将 dynamic chunk size、encryption 场景下的 dedupe 等议题作为 follow-up 记录到 tracker。整体目标是让 GCM encryption 与 life cycle 压缩这两个 feature 尽量赶上 Umbrella 版本，同时在性能优化与实现复杂度之间保持审慎权衡。</p>',38)])])}const g=i(a,[["render",n]]);export{h as __pageData,g as default};
